 "content": "def transform(grid):
    """Build symmetric 3x3 repeated pattern matching the demos."""
    h, w = len(grid), len(grid[0])
    out = [[0] * (3 * w) for _ in range(3 * h)]
    for tile_r in range(3):
        flip_r = tile_r != 1
        for tile_c in range(3):
            # Left and right tiles are horizontal reflections; middle is original.
            flip_c = tile_c != 1
            for r in range(h):
                for c in range(w):
                    sr = h - 1 - r if flip_r else r
                    sc = w - 1 - c if flip_c else c
                    out[tile_r*h+r][tile_c*w+c] = grid[sr][sc]
    return out
